INSERT INTO `quest_template_locale` (`ID`, `locale`, `LogTitle`, `LogDescription`, `QuestDescription`, `AreaDescription`, `PortraitGiverText`, `PortraitGiverName`, `PortraitTurnInText`, `PortraitTurnInName`, `QuestCompletionLog`, `VerifiedBuild`) VALUES
(98515, 'zhTW', '阿塔烏特克寶庫：惡毒之旅', '在阿塔烏特克寶庫完成巡邏、攻擊與入侵點各一次，並擊敗一名遠古強敵。', '這神殿就是烏拉特克之子最先從黏液爬出來的地方。我們得堅守這裡的防線。\n\n敵人的攻勢一波接著一波，從小規模攻擊，到席捲整座神殿的大舉入侵，甚至還有巨獸自毒液中現身。\n\n不管他們派什麼來，都把它們打回邪惡的老家！\n\n這段期間，盡力確保巡邏隊的安全。', '', '', '', '', '', '', 69587),
(98428, 'zhTW', '阿塔烏特克寶庫：腐蝕祭壇', '與艾琳依交談以腐蝕你的靈魂，然後與腐蝕祭壇溝通。', '腐蝕祭壇。\n\n誰知道這塊受詛咒的石頭是何時從毒液中升起的？我花了無數歲月研究它，也才剛嚐到它的一點力量。\n\n<艾琳依舔了舔她的幽靈嘴唇。>\n\n只要你開口，我就會將你身上的腐蝕轉化為更有用的東西。然後，你便能與祭壇溝通，並接受它賜予的眾多恩賜。', '', '', '', '', '', '在歐菲的小屋與她交談。', 69587),
(98420, 'zhTW', '那裡有什麼？', '與其他玩家組隊，偵察阿塔烏特克寶庫。', '知識是戰爭中最關鍵的武器。這座寶庫古老而龐大，我們的斥候無法偵察所有角落。究竟是什麼潛伏在這座被腐化的大廳深處？\n\n這正是我想知道的。去那裡看看，然後告訴我你看到了什麼，但獨自前往很危險。如果你想活著回來，最好帶上幾位戰友。', '', '', '', '', '', '', 69587),
(98419, 'zhTW', '並肩作戰', '與其他玩家組隊，並在阿塔烏特克寶庫中殺死敵人。', '這座寶庫是個危險的地方。很多勇敢又固執的戰士，都以為自己能獨自面對烏拉特克之子。要是他們運氣好，我們還能在他們被吃掉前把屍體找回來。\n\n我很中意你，$p。要是看到毒蛇把你拿去餵幼蛇，那就太可惜了。所以聰明點。找些能幫你留意背後的夥伴，然後一起在神殿裡殺出一條血路吧。', '', '', '', '', '', '', 69587),
(98416, 'zhTW', '船長的請求', '到托卡臺地與托卡船長碰面。', '喔，船長這次心情真的很惡劣。我覺得你最好去看看他想做什麼。\n\n<二副斯拉格搖搖頭。>\n\n最近，只有你能安撫暴跳如雷的他。', '', '', '', '', '', '', 69587),
(98415, 'zhTW', '幫船長一個忙', '到托卡臺地與托卡船長碰面。', '喔！你去釣魚的時候，托卡船長想再見你一面。我猜他開始信任你了。\n\n<二副斯拉格表情扭曲。>\n\n船長的信任不一定是件好事。', '', '', '', '', '', '', 69587),
(98414, 'zhTW', '船長的要求', '到托卡臺地與托卡船長碰面。', '喔，呃。船長要你盡快去托卡臺地跟他會合\n\n<二副斯拉格縮在龜殼裡發抖。>\n\n他臉色不怎麼好看。小心點。', '', '', '', '', '', '', 69587),
(98406, 'zhTW', '精挑細選的禮物', '接受最後的建築師的禮物。', '在烈風海岸這裡，我觀察到你對社區的其他凡人的幫助和照顧。我想鼓勵這種為他人無私奉獻的行為。雖然對你無利可圖，但這正是增進大眾福祉的驅動力。\n\n有鑑於你的努力和成果，我要送你一個禮物。這個小巧裝置內含一件裝飾，可以讓你放在房屋中。我下週會再給你另一個。', '', '', '', '', '', '', 69587),
(98388, 'zhTW', '進入阿塔烏特克寶庫', '找到『勇者』娜札菈、神射手索丘和指揮官嘉芭的下落。', '在這道壁壘之後，只有滿滿的毒蛇、靈魂和致命的毒物。\n\n這週我就失去了三名副官。他們很強大，也很勇敢。或許比你還要強大和勇敢。\n\n<領軍阿杜馬提一臉疲倦地看著你。>\n\n如果你想去深淵闖一闖，那就請便。如果你能在屍骨堆中找到我的斥候，請把他們帶回來。\n\n記得小心你的腳步。毒液會活活吞了你。', '', '', '', '', '', '到阿曼尼據點向領軍阿杜馬提回報。', 69587),
(98343, 'zhTW', '毒液釣魚：我的最佳副手', '到托卡的愚行與二副斯拉格碰面。', '在我派你去狩獵之前，你應該認識一下我剩下的船員。\n\n當然，大多數人都在船難中喪生了。少數人掉進沼澤。至於那些愚蠢的叛徒…我們很快就會逮住他們，不是嗎？\n\n不過我忠心的二副正替我守著據點，就在登陸地點的下游。她會好好照應你。', '', '', '', '', '', '', 69587),
(98311, 'zhTW', '第3週（共3週）：中斷和驅散', '使用中斷或驅散後，在訓練場的競技場或戰場獲勝。', '我還有最後一課要教給你。進去那裡，中斷敵人的施法，或驅散你或盟友身上的有害效果。然後，再擊敗你的敵人兩次。', '', '', '', '', '', '', 69587),
(98295, 'zhTW', '第2週（共3週）：控場', '使用控場後，在訓練場的競技場或戰場獲勝。', '很好，你善用了鬥士的特質加成。現在，我要你在施加控場效果後，試著擊敗一些敵方隊伍！', '', '', '', '', '', '', 69587),
(98234, 'zhTW', '第1週（共3週）：鬥士的特質', '裝備PvP飾品後，在訓練場的競技場或戰場獲勝。', '有興趣和我們的鬥士切磋一下嗎？踏上競技場，讓我們看看你的本領。\n\n記得裝備這些勳章，並擊敗至少兩組敵人。', '', '', '', '', '', '', 69587),
(98232, 'zhTW', '至暗之夜：阿塔烏特克寶庫', '在阿塔烏特克寶庫中完成神殿攻擊、入侵點，並擊敗遠古敵人。', '祖爾賈拉的部隊駐紮在阿塔烏特克寶庫的大門，對抗那些邪惡的毒蛇，守住這條防線。\n\n整個東部王國的命運全繫於他們的成敗。為他們提供援兵會是明智之舉。烏拉特克之子十分兇猛，但面對像你這樣老練的$c，牠們根本不是對手。\n\n穿越神殿，盡你所能削減牠們的數量。', '', '', '', '', '', '', 69587),
(98229, 'zhTW', '劇毒深淵：圖窮匕現', '在傳奇難度的劇毒深淵中，收集3個面具碎片。', '如果我的弟弟不再臣服於瑪拉克雷斯，那他的處境一定十分危險。我們必須想辦法盡快找到他們。找找看有沒有能讓我們更快穿越神殿的東西。', '', '', '', '', '', '', 69587),
(98228, 'zhTW', '劇毒深淵：圖窮匕現', '在英雄難度的劇毒深淵中，收集3個面具碎片。', '如果我的弟弟不再臣服於瑪拉克雷斯，那他的處境一定十分危險。我們必須想辦法盡快找到他們。找找看有沒有能讓我們更快穿越神殿的東西。', '', '', '', '', '', '', 69587),
(98226, 'zhTW', '劇毒深淵：圖窮匕現', '在普通難度的劇毒深淵中，收集3個面具碎片。', '如果我的弟弟不再臣服於瑪拉克雷斯，那他的處境一定十分危險。我們必須想辦法盡快找到他們。找找看有沒有能讓我們更快穿越神殿的東西。', '', '', '', '', '', '', 69587),
(98218, 'zhTW', '回到阿曼尼扎', '到阿曼尼扎村與莉雅德倫交談。', '$n：\n\n阿曼尼扎村需要你的援助。請到那裡找我。\n\n--莉雅德倫', '', '', '', '', '', '到阿曼尼扎村找莉雅德倫。', 69587),
(98204, 'zhTW', '受詛咒的遺物', '移除腐化，淨化遺物。', '<抑制護盾嗡嗡作響，緊緊包覆著遺物。這件物品散發悲傷和痛苦的氣息。\n\n據最後的建築師所說，這個遺物受到詛咒，但能夠進行淨化。只需將自我的本源融入這件物品中，再從內部移除腐化即可。這會危險到哪裡去？>', '', '', '', '', '', '', 69587),
(98172, 'zhTW', '追蹤薩拉塔斯', '收集$1oa個消逝虛無低語。\n\n這些虛無殘餘可以從地城、探究、寶藏和其他危險生物身上獲取。', '$n，我們絕不能迷失我們在銀月城這裡的真正目的：將薩拉塔斯繩之以法。\n\n在太陽之井，我們都見識到她的虛無大軍。他們向下猛衝，進入太陽之井，而且數量龐大。如今卻毫無動靜。\n\n聆聽他們的低語，$c。幸運的話，我們能夠再次捕捉他們的行蹤，然後找到薩拉塔斯…甚至找到那些追殺她的人。', '', '', '', '', '', '回到銀月城找凡蕾莎‧風行者。', 69587),
(97978, 'zhTW', '稜彩潛能', '收集$1oa個你從至暗之夜第2賽季的團隊副本首領、豐碩探究、傳奇鑰石地城和夢魘狩獵中取得的基礎虛無之核裂片，幫助歐林進行他的催化器研究。\n\n催化器將賦予額外星雲虛無之核的使用權，用來取得來自團隊副本首領、傳奇鑰石地城、豐碩探究和夢魘狩獵中的強力物品。', '你好，$C。我們的共同好友向我們解釋了一切。別擔心，我和我的陰影對戴西蒙斯的虛無編織已經駕輕就熟。\n\n我們有個想法。催化器的轉化能量極為龐大，涵蓋眾多已知的元素之力。\n\n如果我能把虛無從那個能量光譜中獨立出來，就能用它編織星雲虛無之核，就像戴西蒙斯利用虛無熔爐所做的事。\n\n但，我們不是多曼納爾。我們必須慢慢來。', '', '', '', '', '', '', 69587),
(97945, 'zhTW', '在催化器的陰影中', '到銀月城與歐林‧逸光交談。', '啊，$n！很好。既然你幫我收集了這麼多資源，我也該去尋求其他…利益了。\n\n什麼？你期待有更戲劇性的背叛場面？不可能！\n\n別擔心，$p，儘管我可能分身乏術，但你的冒險總是讓我看得津津有味。\n\n當然，冒險者仍受我的恩賜庇護。很多人都很有意思，不過我只覺得某個虛無精靈…古怪得令人發笑，值得栽培一番。\n\n他的名字是歐林‧逸光。你可以在銀月城的催化器旁找到他。', '', '', '', '', '', '', 69587),
(97910, 'zhTW', '破裂的鑰石', '通關任何傳奇2以上難度的地城。', '當你觸摸石頭時，英勇事蹟的零碎畫面在你腦中一閃而過，但它們隨即便消失了。\n\n或許完成一個足夠令人敬佩的任務，可以讓石頭的魔法再次穩定下來？', '', '', '', '', '', '', 69587),
(97672, 'zhTW', '一堆虛光泥灰', '', '', '', '', '', '', '', '', 69587),
(97670, 'zhTW', '一把虛光泥灰', '', '', '', '', '', '', '', '', 69587),
(97669, 'zhTW', '受縛靈魂的好運', '把山貓掌拿給艾琳依。', '<你手中握著一隻普通的山貓掌，這是靈魂作為臨別贈禮留下的東西，飽受歲月和苦惱摧殘。\n\n但其中充滿了這悲慘地方中每個遇見它的受縛靈魂懷抱的希望與恐懼。\n\n儘管令人膽寒，但結果頗為驚人。艾琳依應該會想研究這東西。>', '', '', '', '', '', '在歐菲的小屋與她交談。', 69587),
(97668, 'zhTW', '札里斯的守望凝視', '把札里斯之眼拿給艾琳依。', '<緊握這顆蛇眼，一股異樣的寒意悄悄爬上你的後頸。\n\n是烏拉特克的蛋，且數以百計。你能感受到它們的每一次抽動，正靜待著破殼的瞬間，隨時會爆發出致命毒液，並誕下更多烏拉特克那令人憎惡的子嗣。\n\n你恨不得將它扔進世上最深的墓穴，但它的力量不容小覷，艾琳依應該會想研究這東西。>', '', '', '', '', '', '在歐菲的小屋與她交談。', 69587),
(97662, 'zhTW', '托加拉之風', '把托加拉之羽拿給艾琳依。', '<隨著你握住手中脆弱的羽毛，一陣幽靈般的風拂過寶庫。\n\n你感到靈魂承受的腐蝕重擔減輕，似乎可以張開雙翅，直接飛出這個詛咒之地。\n\n想當然爾，你並不能。但艾琳依應該會想進一步研究這東西。>', '', '', '', '', '', '在歐菲的小屋與她交談。', 69587),
(97661, 'zhTW', '梅德嘉的守護', '把梅德嘉護符拿給艾琳依。', '<護符在你手中感覺溫暖又光滑。\n\n你感覺自己卸下了腐蝕的重擔，就像是護符保護你免於受烏拉特克的詛咒影響。\n\n艾琳依應該會想研究這東西。>', '', '', '', '', '', '在歐菲的小屋與她交談。', 69587),
(97640, 'zhTW', '阿塔烏特克寶庫：多餘的硬幣', '找到艾琳依。', '你看起來不太好，$p。\n\n<阿杜馬提嚴肅地檢視著你，你的心跳加快，視野變成綠色。你口袋裡的硬幣重量感覺難以承受。>\n\n你在外頭找到某些東西了，是吧？寶庫裡滿滿都是寶物，大多數都受到詛咒。\n\n我不信任她，但你看到的那個靈魂女巫熟悉這恐怖地方的所有秘密。如果有人能幫得上忙，肯定非她莫屬。', '', '', '', '', '', '到阿曼尼據點與艾琳依交談。', 69587),
(97625, 'zhTW', '光榮豐足', '為豐足羅亞採集財寶。', '雖然豐足羅亞並非四大羅亞之一，但祂的信徒絕對是最虔誠的。\n\n親自去找他吧。你可以在祖阿曼北部的哈拉齊神廟附近找到祂，但我聽說祂也在永歌森林、哈朗達，甚至透過巨大的天之口在虛無之地建立了採集據點。\n\n就算沒有其他好處，祂賜予的獎勵也十分豐厚，至少對那些有價值者來說。', '', '', '', '', '', '', 69587),
(97624, 'zhTW', '追尋傳說', '發現一個哈拉尼爾的傳說。', '$n，哈朗達的每一段歷史記錄都蘊藏著智慧。你最好親自去探尋它的傳說。我想你或許能藉此了解這個世界，還有我們在其中的定位。', '', '', '', '', '', '', 69587),
(97622, 'zhTW', '印象深刻的晚會', '參加薩瑟里的晚會並強化永歌森林的符石。', '你想晉見薩瑟里？穿成…這樣？請容我摀著手帕笑一下。\n\n<凱利斯在手帕底下發出輕笑。>\n\n好了，讓我表現得專業一點。誠摯邀請你參加薩瑟里的晚宴。\n\n別讓自己出洋相，$n。銀月城的佼佼者們都在看著。', '', '', '', '', '', '', 69587),
(97621, 'zhTW', '奇異點錨', '在風瑪利昂堡壘守護奇異點錨。', '我們在這個世界的逗留，讓刃多雷對虛無有了比以往更深刻的理解。與我們擁有共同敵人的多曼納爾，以幾乎可以說是詭異的慷慨，與我們分享他們的知識。我認為他們想讓我們變得和他們一樣令人畏懼。\n\n在風瑪利昂堡壘裡有一個奇異點錨。我已經學會了如何抽取它的部分力量，為你打造一件強大的物品。\n\n但首先，我們必須確保它不會落入敵人手中。', '', '', '', '', '', '', 69587),
(97616, 'zhTW', '腐蝕贈禮：腐蝕之力', '將纏魂者寶典帶到阿塔烏特克寶庫中的腐蝕祭壇。', '<當你將這本古書拿在手中時，你覺得氣氛為之一變。\n\n儘管它讓你的皮膚感到刺痛與灼熱，無數思緒卻在你心中浮現，關於它所蘊含的力量，以及它所代表的凶險。\n\n你必須知道更多。\n\n在這座小島上，只有一個地方能夠容納這本褻瀆的古書。你用心靈之眼瞥見腐蝕祭壇。>', '', '', '', '', '', '', 69587),
(97571, 'zhTW', '捕獵鏢鱸', '把$1oa隻骯髒鏢鱸拿給飲鹵者基爾斯。', '骯髒鏢鱸。可惡的討厭鬼。\n\n牠們在水中游的樣子讓人非常不適、不安，害你不禁想像牠們直直落入自己的胃…\n\n<基爾斯大聲咳了咳>\n\n你可以盡一份力，帶幾隻來給我，從水域中清除那些邪惡的東西。', '', '', '', '', '', '', 69587),
(97565, 'zhTW', '搞定有鱗的東西', '在阿塔烏特克寶庫中釣起疫牙並擊殺牠。', '<你收集的鬼東西瞬間消失，隨後化為一體，同時再次出現。>\n\n去吧，拿走吧。把它拿去阿塔烏特克寶庫。把它接上你那陰暗的竿子，丟進惡臭的池子，抓出烏拉特克的寵物。你懂在任何地方垂釣的技術，對吧？', '', '疫牙是隻可怕的生物，其血管中脈動著烏拉特克的詛咒。不能讓牠繼續成長，並逃離寶庫。', '疫牙', '', '', '使用怪異小珠製造一片深淵漩渦，並在其中釣魚', 69587),
(97562, 'zhTW', '排除鱂魚', '把$1oa隻班點鱂魚拿給飲鹵者基爾斯。', '班點鱂魚。噁心的小東西。\n\n這種小小惡魔就像蟲子一樣群聚，沖上海岸的數量之多，得花上好幾餐才能吃得完。\n\n<基爾斯的肚子發出響亮的咕嚕聲。>\n\n你可以盡一份力，帶幾隻來給我，從水域中清除那些邪惡的東西。', '', '', '', '', '', '', 69587),
(97559, 'zhTW', '熟悉毒味', '在盤蛇島完成詛咒狂湧，從烏拉特克的信徒身上取回殘骸。', '你現在肯定理解烏拉特克造成的威脅了，對吧？她駭人的力量一次又一次地滲出。\n\n如果要我完成自己份內的事，我需要你先證明你對…該說是我們的合約嗎？證明你對合約是否忠實。她的侍僧再次召喚那些扭曲雜碎時，殺光他們，把殘骸收集起來。', '', '', '', '', '', '使用怪異小珠製造一片深淵漩渦，並在其中釣魚。', 69587),
(97557, 'zhTW', '追尋特哈比魚', '把$1oa隻劇毒特哈比魚拿給飲鹵者基爾斯。', '劇毒特哈比魚。這種魚非常麻煩。\n\n牠們全身都不對勁，那雙大圓眼睛，還有甜美、肥滿的魚肉…\n\n<基爾斯清了清喉嚨。>\n\n更別說還有毒性了。少了牠們的危害，大海會變得更美好。', '', '', '', '', '', '', 69587),
(97535, 'zhTW', '你不會拒絕的交易', '在毒液高地收集$1oa個亞基蟲之顎。', '<某種聲音在你心中嘶嘶作響。>\n\n我只不過是你毫無意義的征戰之中另一個受害者嗎？我真想知道…你會把我活剝，丟進鍋裡煮嗎？或是任我在其他剩餘的事物中腐爛？\n\n如果我能給你…某些更好的東西呢？某種…美味的東西。烏拉特克之子是這世界的毒瘤。這點我們可以同意。把你殺死他們的證物帶來給我。', '', '', '', '', '', '使用怪異小珠製造一片深淵漩渦，並在其中釣魚。', 69587),
(97521, 'zhTW', '海龜重返大海', '拾取宣傳用材料，向本地社區居民宣傳水下旅店。', '你好啊，拓荒者！\n\n海岸邊有個海灣，我的同胞們把那地方改建成了旅店。那裡全年無休，但我們來的時候喜歡讓他們有些生意可做。你介意幫個忙嗎？', '', '', '', '', '', '', 69587),
(97492, 'zhTW', '', '', '', '', '', '', '', '', '', 69587),
(97491, 'zhTW', '', '', '', '', '', '', '', '', '', 69587),
(97482, 'zhTW', '追憶毒牙', '升級你的裝備，直到你能在阿茲塔瑞的巢穴中迎戰他。', '那隻毒蛇怪物非常凶狠，毒液足以融化岩石。\n\n在我們實際嘗試擊倒他之前，得先準備最好的裝備才行。\n\n不過我有幾個點子，讓我們能反過來利用那毒液，立刻展開行動。', '', '', '', '', '', '', 69587),
(97465, 'zhTW', '正確捕魚方法', '到托卡的愚行與二副斯拉格碰面。', '<是一把長矛。這釣竿是一把長矛。\n\n斯拉格可能認得這物品。>', '', '', '', '', '', '到托卡的愚行與二副斯拉格碰面。', 69587),
(97464, 'zhTW', '一點毒藥', '到托卡的愚行與二副斯拉格碰面。', '<玻璃經過強化，非常的厚，顯示內容物可能非常危險…或是貴重。裡頭翠綠色的液體隨著容器晃動時閃爍著微光。\n\n你覺得聞到了某種刺鼻、噁心的味道。但也可能是因為整座島聞起來都刺鼻、噁心。\n\n斯拉格可能認得這物品。>', '', '', '', '', '', '到托卡的愚行與二副斯拉格碰面。', 69587),
(97463, 'zhTW', '只是把普通小刀', '到托卡的愚行與二副斯拉格碰面。', '<這把刀刃沒有任何磨損的跡象，倒是有著受到細心保養的痕跡。用途明顯是用於祭祀，但究竟是用在什麼樣的祭禮？\n\n金屬上頭的紅色微光讓你有了點頭緒。\n\n斯拉格可能認得這物品。>', '', '', '', '', '', '到托卡的愚行與二副斯拉格碰面。', 69587),
(97462, 'zhTW', '岩石海岸', '到托卡的愚行與二副斯拉格碰面。', '<這塊有刻面的礦石散發出令人不安的能量低鳴。究竟是實際用途還是奇妙的特性使它有其價值，你無從判斷。\n\n你有種想舔它的衝動，但你很清楚不該這麼做。\n\n斯拉格可能認得這物品。>', '', '', '', '', '', '到托卡的愚行與二副斯拉格碰面。', 69587),
(97461, 'zhTW', '詛咒釣法入門', '到托卡的愚行與二副斯拉格碰面。', '<大多數釣魚教學都重視魚餌、天氣，和耐心。這本飽經風霜的典籍強調對競爭對手施加妖術，還有和深海溝通的方法。\n\n你感覺自己正步入深不可測的危險水域。\n\n斯拉格可能認得這物品。>', '', '', '', '', '', '到托卡的愚行與二副斯拉格碰面。', 69587),
(97460, 'zhTW', '稍微加鹽', '到托卡的愚行與二副斯拉格碰面。', '<小包頗不起眼，但它的歷史可不一般。儀式用鹽一直以來都被用來召喚先祖、靈魂，以及不屬於凡人世界的力量。\n\n因為長期泡在海水的關係，這鹽巴味道鹹得發苦，或許也因此威力倍增？\n\n斯拉格可能認得這物品。>', '', '', '', '', '', '到托卡的愚行與二副斯拉格碰面。', 69587),
(97459, 'zhTW', '臭臭的東西', '到托卡的愚行與二副斯拉格碰面。', '<銘文不只能吸引靈魂，如果燃燒了夠多，還能讓它們陷入凶暴的狂亂狀態。這肯定不會有好下場。\n\n不過，聞起來確實味道不錯。\n\n斯拉格可能認得這物品。>', '', '', '', '', '', '到托卡的愚行與二副斯拉格碰面。', 69587),
(97458, 'zhTW', '釣具箱收好', '到托卡的愚行與二副斯拉格碰面。', '<無窮無盡的釣魚用品會是大多數釣手的美夢。這釣具箱每次開啟都會尖叫，應該就是它沉入海底深處的原因。\n\n和它相處足夠時間後，就算不打開也會聽見尖叫聲的回音。\n\n斯拉格可能認得這物品。>', '', '', '', '', '', '到托卡的愚行與二副斯拉格碰面。', 69587),
(97457, 'zhTW', '像手套一樣合身', '到托卡的愚行與二副斯拉格碰面。', '<這些看起來像是很大的一雙手骨，某人把這些挖成中空，聲稱是護手。\n\n幸好你已經有護手了，否則你也會禁不住想試戴看看。\n\n斯拉格可能認得這物品。>', '', '', '', '', '', '到托卡的愚行與二副斯拉格碰面。', 69587),
(97455, 'zhTW', '鐘聲呼喚', '到托卡的愚行與二副斯拉格碰面。', '<被海浪沖洗的歲月早該害細節磨損，但鐘的保存狀況卻非常良好。不論它原先的目的為何，上頭銘刻的符文肯定是為了讓它能長久保存。\n\n你正想搖響它，但霎時產生某種不好的預感。最好別這麼做。\n\n斯拉格可能認得這物品。>', '', '', '', '', '', '到托卡的愚行與二副斯拉格碰面。', 69587),
(97454, 'zhTW', '賽季複習課程：至暗之夜', '複習探究者指南，並向娜蕾迪亞‧河光和傳送師艾司川迪斯購買賽季補給品。', '自從盤蛇島開放之後，探究又變得更加有趣了。\n\n看看東道主能不能分點東西，給我們這些實際冒險的人用，也記得看看探究者指南的內容有沒有更新。\n\n稍微複習一下有益無害。', '', '', '', '', '', '', 69587),
(97384, 'zhTW', '更多靈魂腐蝕', '把腐蝕寶石拿給阿塔烏特克寶庫的艾琳依。', '其中一個纏魂者身上帶著這寶石。你該拿去給艾琳依看看。', '', '', '', '', '', '', 69587),
(97383, 'zhTW', '靈魂腐蝕', '把腐蝕文物拿給阿塔烏特克寶庫的艾琳依。', '我們的斥侯在某個墓穴裡找到了這個文物。或許艾琳依會知道該拿它怎麼辦？', '', '', '', '', '', '', 69587),
(97382, 'zhTW', '詛咒反制獎賞', '擊敗一波詛咒狂湧。', '這個小島的一切都被詛咒了，$n。當烏拉特克的詛咒融入戰鬥中，最重要的事就是反擊。我們需要每一分助力，才能把它拒於門外。\n\n你看起來很強…不過，如果你想要活下去，就需要更好的裝備。\n\n擊敗其中一波狂湧的首領，然後我們就能討論獎勵的事。', '', '', '', '', '', '', 69587),
(97321, 'zhTW', '滑溜戰利品', '聆聽瓦麗拉的故事。', '我有好消息，也有壞消息。\n\n壞消息是，我們找到的那些珍品全都融化了。\n\n好消息呢？我找到某種有趣的毒素可以使用。\n\n但先讓我解釋發生了什麼事…', '', '', '', '', '', '', 69587),
(97256, 'zhTW', '擊倒首領（英雄）', '在英雄世界級別下的衛爾和奈格塔，從奧核隊長雷席爾或統治者佩堤納斯身上收集4個虛無指揮官紋章。', '親眼看到最偉大的勇士灰飛煙滅時，就連是最沒血沒淚的生物也會心生動搖。\n\n提醒我們在這裡的敵人，他們的首領倒下的速度有多快！\n\n讓他們見識艾澤拉斯的怪物到底有多無情、多邪惡！把虛無指揮官紋章交給我，我會給你應得的獎勵。', '', '', '', '', '', '', 69587),
(97215, 'zhTW', '第二波攻勢', '在虛無風暴與裂刃梅拉會合。', '我們已經重創敵人。儘管如此，他們仍持續發動襲擊。\n\n戴西蒙斯和我的裂隙看守者已鎖定另一個世界，那裡正是他們發動這些攻擊的地點。\n\n我軍主力已暫時撤回虛無風暴，以便開始進攻這第二個世界。\n\n我們的突擊小隊正在咆哮峰等著我們。', '', '', '', '', '', '在虛無風暴的咆哮峰與裂刃梅拉碰面。', 69587),
(97147, 'zhTW', '阿曼尼部族特使', '', '', '', '', '', '', '', '', 69587),
(97142, 'zhTW', '糖果桶', '', '', '', '', '', '', '', '', 69587),
(97141, 'zhTW', '寶庫戰利品', '參與阿塔烏特克寶庫中的活動。', '我們需要傾盡全力，才能防止烏拉特克的部隊襲捲整個小島。主戰場是在烏拉特克寶庫內部，迎戰她源源不絕的子嗣。殺了一隻，又有兩隻從毒液中爬出來。\n\n勇闖戰場，$n，助我們疲憊的鬥士一臂之力。誰知道呢？說不定你還能在那個古老的詛咒之地找到一些值錢的東西。', '', '', '', '', '', '', 69587),
(97128, 'zhTW', '巢穴：妮莉莎‧喚浪者', '', '', '', '', '', '', '', '', 69587),
(97089, 'zhTW', '任務堆積如山', '', '', '', '', '', '', '', '', 69587),
(97088, 'zhTW', '任務堆積如山', '', '', '', '', '', '', '', '', 69587),
(97087, 'zhTW', '積極干擾：奈格塔（英雄）', '透過完成世界任務、事件或尋找寶藏來干擾奈格塔的赫哈達。', '他們的熔爐臭味依然揮之不去。這意味著他們正在重建。\n\n如果你希望能徹底瓦解他們的行動並消除威脅，就必須堅持下去。\n\n好了，出發吧。去盡情破壞。', '', '', '', '', '', '', 69587),
(97086, 'zhTW', '危險敵人：奈格塔（英雄）', '在奈格塔除掉稀有和精英敵人。', '我聽到你的斥侯們在討論他們所面對過的危險生物與強敵。\n\n這讓我好奇你是否能擊敗他們？你何不親自去試試，這肯定對你在這裡的行動大有幫助。\n\n希望你回來的時候，我能看到你沒有缺手斷腳。', '', '', '', '', '', '', 69587),
(97085, 'zhTW', '危險敵人：奈格塔', '在奈格塔除掉稀有和精英敵人。', '我聽到你的斥侯們在討論他們所面對過的危險生物與強敵。\n\n這讓我好奇你是否能擊敗他們？你何不親自去試試，這肯定對你在這裡的行動大有幫助。\n\n希望你回來的時候，我能看到你沒有缺手斷腳。', '', '', '', '', '', '', 69587),
(97084, 'zhTW', '積極干擾：奈格塔', '透過完成世界任務、事件或尋找寶藏來干擾奈格塔的赫哈達。', '他們的熔爐臭味依然揮之不去。這意味著他們正在重建。\n\n如果你希望能徹底瓦解他們的行動並消除威脅，就必須堅持下去。\n\n好了，出發吧。去盡情破壞。', '', '', '', '', '', '', 69587),
(97083, 'zhTW', '危險敵人：衛爾（英雄）', '在衛爾除掉稀有和精英敵人。', '我們的斥侯回報，他們發現有危險的精英生物正在阻礙我們的行動。\n\n我需要你前去解決掉他們，好讓我們能繼續執行首要任務。', '', '', '', '', '', '', 69587),
(97082, 'zhTW', '危險敵人：衛爾', '在衛爾除掉稀有和精英敵人。', '我們的斥侯回報，他們發現有危險的精英生物正在阻礙我們的行動。\n\n我需要你前去解決掉他們，好讓我們能繼續執行首要任務。', '', '', '', '', '', '', 69587),
(97081, 'zhTW', '積極干擾：衛爾（英雄）', '透過完成世界任務、事件或尋找寶藏來干擾衛爾的多曼納爾部隊。', '我們絕不能停止施加壓力。就算在此刻，他們仍然在從我們的攻擊中重振旗鼓。\n\n再次出擊，讓他們見識何謂毫不留情！', '', '', '', '', '', '', 69587),
(97080, 'zhTW', '積極干擾：衛爾', '透過完成世界任務、事件或尋找寶藏來干擾衛爾的多曼納爾部隊。', '我們絕不能停止施加壓力。\n\n就算在此刻，他們仍然在從我們的攻擊中重振旗鼓。\n\n再次出擊，讓他們見識何謂毫不留情！', '', '', '', '', '', '', 69587),
(97077, 'zhTW', '暗中出擊', '與投影裝置互動來引誘出英波特斯。', '既然我們的陷阱已經同調完成，現在只需要把獵物誘騙到開闊地帶即可。\n\n出於策略需要…我拆解了…我取得的那台投影裝置的部分零件。英波特斯現在應該很難看清楚你和聽見你。\n\n聲稱你是他的盟友，要求立即見面。我們就指望他的好奇心會戰勝理智吧。\n\n然後…\n\n<雷歐娜舉起注入虛無的寶石，凝視了片刻，隨後對你點了點頭。>', '', '英波特斯一心追求權力，且對艾澤拉斯興趣缺缺，他是安插在衛爾的完美人選。', '英波特斯', '', '', '回到衛爾找戴西蒙斯。', 69587),
(97075, 'zhTW', '優質商品', '', '', '', '', '', '', '', '', 69587),
(97073, 'zhTW', '鏽栓鎮零售商', '', '', '', '', '', '', '', '', 69587),
(97072, 'zhTW', '歡迎來到沼澤般的奈格塔', '使用光幕召回信標返回奈格塔的晦影營地。', '奧核隊長就在那座山丘後方，完全沒有發現我們的到來。\n\n現在發動攻擊確實能讓他的軍隊措手不及…但很可能也會導致我們的覆滅。\n\n無論如何，若想成功，我們都需要盟友。\n\n使用這個信標回到我們的入侵點。\n\n現在，伊梅拉很可能已經帶著其餘的部隊來支援我們了。\n\n等你到了之後就去和梅拉談談。', '', '', '', '', '', '在奈格塔的晦影營地與裂刃梅拉交談。', 69587),
(97071, 'zhTW', '歡迎來到寒冷的衛爾', '使用光幕召回信標返回衛爾的晦影營地。', '即便掌握了奇襲優勢，要是沒有盟友，我們依然處於劣勢。\n\n獨自衝進佩堤納斯的要塞無異於自尋死路。\n\n拿著塔拉桑給我們的這個信標，回到我們的進入點。\n\n我會在那裡和你會合，並把我的報告交給梅拉。\n\n希望那裡有某種避難所可以接應我們。', '', '', '', '', '', '在衛爾的晦影營地與裂刃梅拉交談。', 69587),
(97037, 'zhTW', '黯星啟示', '與大法師伊梅拉交談，了解關於全像寶石的事。', '我們有麻煩了，$n。\n\n從你找到的全像寶石中，我得知同胞們在這個世界的過去，和那些警戒傀儡生前是什麼人了。\n\n他們是誰不是問題，問題是附身在機體內部的東西。\n\n附身在機體內的東西現在落到了靈魂建築師手中，而根據斥侯的報告，他已經離開奈格塔了。\n\n大法師伊梅拉會進一步解釋的。', '', '', '', '', '', '把全像寶石拿到虛無風暴的咆哮峰給『三度流放者』圖阿瑪。', 69587),
(97036, 'zhTW', '晦影頭銜賽', '透過冰川蓄池前往平台，並擊敗劍仕瑞吉納斯。', '很好，看來我們的目標比以往更加一致了。你確實令我刮目相看。隨著伊納督斯和佩里庫勒斯被除掉，剩下的就只有我以前那位同僚了。\n\n你可以在那個高台上找到劍仕瑞吉納斯，她就在那裡觀察獵物。她已經知道你會來了，所以別想著偷襲她。反正你也只有一條路能上去，就是穿過冰川蓄池裡的那道傳送門。\n\n我會履行我的職責加入你。作為我們…合作的象徵。', '', '劍仕瑞吉納斯或許是這些新晉多曼納爾當中最危險的一位。她以擅長煽動對手自相殘殺，以及在背後捅盟友一刀而聞名。', '劍仕瑞吉納斯', '', '', '在衛爾與戴西蒙斯會合。', 69587),
(97035, 'zhTW', '推翻狂亂者', '進入衛爾的遺忘深淵尋找佩里庫勒斯，然後擊敗他。', '擊敗伊納督斯確實令人印象深刻，雖然我是這麼想的，但這並不代表你離奪取衛爾又更接近了。佩里庫勒斯絕不會讓你碰他的玩物。\n\n他是一個…可以說，很古怪的傢伙，且對你們這些血肉之軀有著病態般的癡迷。\n\n你很可能會在這個世界最黑暗的深淵裡找到他，他會在那裡剖開佩堤納斯收集來的牲畜。\n\n他很喜歡戲弄獵物，所以我建議你小心為上。', '', '佩里庫勒斯熱愛對血肉之軀進行殘酷的實驗，他對這些生物的解剖構造有著一種令人畏懼的著迷。', '佩里庫勒斯', '', '', '回到衛爾找英波特斯。', 69587),
(97034, 'zhTW', '擊敗好戰者', '擊敗虛無衛城中的虛無部隊來引出伊納督斯，之後擊敗他，取得他的護甲。', '可憐的英波特斯似乎不相信我們能從他惡毒的同夥手中奪取主控權。他的想像力真是可悲。\n\n我們只需讓他看看團結的力量。殺死那個新來的蠻徒伊納督斯吧。我想他的護甲穿在我們的新救星身上應該很合適。\n\n伊納督斯似乎很謹慎，不在他人面前露面，但他顯然很容易被激怒。進去製造一些騷動吧，這似乎是你最擅長的事。我期待他也會發動反擊。', '', '伊納督斯是位殘暴的好戰分子，意圖繼續向艾澤拉斯發起襲擊。', '伊納督斯', '', '', '把護甲交給衛爾的英波特斯。', 69587),
(97031, 'zhTW', '威拉頓告別', '將全像寶石送回晦影營地交給大法師伊梅拉。', '<黑影中，一道閃爍的微光吸引了你的注意。\n\n隨著你拾起滿是灰塵的物品，其中央的寶石略為閃爍，奇妙的異星符文閃過表面。\n\n有一瞬間，你看到投影的紀錄閃爍，秀出一位男性德萊尼，口中念著無聲的話語。\n\n伊梅拉肯定會對這個物品有興趣的。>', '', '', '', '', '', '將全像寶石帶回晦影營地交給大法師伊梅拉。', 69587),
(97026, 'zhTW', '奇妙的食材', '在沼澤內歐菲的小屋與她交談。', '<這些平淡無奇的材料有種奇妙的光芒，就好像你注意到其中蘊含著你之前無法發現的力量。\n\n這肯定和你近來一直吸收的腐蝕有關係。\n\n你不確定要怎麼解放其中潛藏的力量，但或許有人更熟悉島上的奇妙魔法，能幫得上你的忙。>', '', '', '', '', '', '在托卡臺地找到狡猾的歐菲。', 69587),
(97016, 'zhTW', '混合奧秘', '將三種強效食材帶去給狡猾的歐菲。', '你覺得你為我的燉菜準備了些厲害的食材，是嗎？我們來看看靈魂們怎麼想。\n\n讓我看看你帶了什麼，我會把它們丟進大鍋裡。靈魂們會飽餐一頓，如果它們喜歡，你可能會得到獎勵。\n\n要是它們討厭，那就會有懲罰。所以，謹慎選擇吧！', '', '', '', '', '', '', 69587),
(96995, 'zhTW', '力挽狂瀾', '擊敗$1oa波詛咒狂湧。', '神殿已經無法再遏制烏拉特克的憤怒。她最兇殘的子嗣正傾巢而出，遍布整座島嶼！如果我們不擋住這股毒液狂潮，牠們會毀掉我們所有人。\n\n在牠們敢露出那張醜臉的地方消滅牠們。絕不能讓牠們站穩陣腳。', '', '', '', '', '', '', 69587),
(96960, 'zhTW', '水池', '', '', '', '', '', '', '', '', 69587),
(96942, 'zhTW', '死吧，隊長！', '', '', '', '', '', '', '', '', 69587),
(96941, 'zhTW', '相應懲罰', '', '', '', '', '', '', '', '', 69587),
(96935, 'zhTW', '詛咒狂湧', '', '', '', '', '', '', '', '', 69587),
(96890, 'zhTW', '祖爾賈拉的部隊特使', '', '', '', '', '', '', '', '', 69587),
(96845, 'zhTW', '爪鉤專家', '對紫色蘑菇和空中孢子使用光鑄鉤槍。', '你一定得試試這個光鑄鉤槍！來，這把出借用的給你試試。要學會怎麼用，先試著對這附近的蘑菇或空中孢子使用看看吧。再回來找我，我就給你可以留著用的鉤槍。', '', '', '', '', '', '', 69587),
(96831, 'zhTW', '博學者的召喚', '到博學者殿堂找奧姆里克和洛摩斯。', '博學者奧姆里克傳話來，說他和洛摩斯找到線索，能幫你繼續強化萬象儀對開本了。', '', '', '', '', '', '', 69587),
(96809, 'zhTW', '外部法力熔爐移位裝置', '在奈格塔各處啟動法力熔爐移位裝置。', '穿梭在這片充滿孢子的岩石地帶很快就變成了一件苦差事，我相信你也會同意這一點。\n\n幸好，我已經想出了一個方法，來利用那些在我們抵達之前就貼心建好的法力熔爐移位裝置網路。\n\n我可以教你如何「啟動」它們供我們使用。你可以從那個讓我們…移位傳送回營地的裝置開始。', '', '', '', '', '', '', 69587),
(96801, 'zhTW', '召集所有的戰鬥者！', '前往銀月城的獵鷹之翼廣場，向米弗丹詢問廣告的事。', '<你讀起附近的一則廣告…>\n\n跑起來，別慢慢走！\n\n工匠聯盟與銀月城當地的工匠合作，在獵鷹之翼廣場提供精挑細選的全新徽章和製作裝備。向你保證，絕對都通過認證，適用於競技場和戰場！\n\n快點去找米弗丹，領取今天的免費樣品。\n\n數量有限，先搶先贏！適用相關使用條款與限制。\n\n-艾莎', '', '', '', '', '', '', 69587),
(96794, 'zhTW', '亡者之怒', '', '', '', '', '', '', '', '', 69587),
(96780, 'zhTW', '當地卡法商店', '', '', '', '', '', '', '', '', 69587),
(96746, 'zhTW', '孢子之殞：腐沼', '進入孢子之殞並擊敗腐沼。', '需要幫忙！哈朗達完蛋了！世界末日要來了！\n\n孢子風暴正在為怨鬥坑洞製造新的東西，但太超過了。太超過了！無法控制。它會掙脫束縛！毀掉坑洞。毀掉我們所有人！\n\n必須去孢子之殞，在它們失控之前摧毀腐沼！\n\n為了哈朗達！為了艾澤拉斯！為了怨鬥坑洞！', '', '腐沼是有史以來最龐大的威脅！除非我們阻止它，否則它將會摧毀哈朗達、艾澤拉斯，然後是怨鬥坑洞！就是照這個順序。總之斯波米爾是這麼說的。', '腐沼', '', '', '', 69587),
(96745, 'zhTW', '空中孢子', '通過飄浮在巨大蘑菇上方的孢子，然後回去找齊凡。', '現在用空中孢子練習看看吧。就在上面而已，只要你知道在哪就行。用那些來飛向天際吧！\n\n你需要在蘑菇上彈跳才能到孢子那邊並看到它們。一旦你到了上頭，就穿過空中孢子，體驗它們的效用吧！', '', '', '', '', '', '', 69587),
(96744, 'zhTW', '彈力蘑菇', '從巨大蘑菇頂端和周圍的生物身上收集樹冠樣本。將它們帶去奈格塔哨站給齊凡。', '哈囉！告訴你一個在紫色蘑菇上彈跳的小技巧。你會用得上的，因為…\n\n我想從上頭的孢子魟魚身上取得一些樹冠樣本。彈到上面去，收集一些樣本，再回來下面，我就教你怎麼樣才能一直在蘑菇上彈跳。', '', '', '', '', '', '', 69587),
(96733, 'zhTW', '進階儀式地點研究：第6週（共6週）', '在啟用餘燼和化身挑戰的情況下，干擾兩個級別6儀式地點。', '歡迎回來，我最出色的學生。我有最後一項任務要交給你，而這項任務將會是一個挑戰。\n\n他們在這些儀式中使用的餘燼，我至今仍無法成功複製，也找不到反制的方法。\n\n我有最後一個想法想讓你去嘗試。你曾回報看過施法者靈魂的魔法化身，我有一個理論，如果同時存在這兩項挑戰，或許能有辦法讓它們互相抵銷。', '', '', '', '', '', '', 69587),
(96732, 'zhTW', '進階儀式地點研究：第5週（共6週）', '在啟用惡意恩澤和巡邏挑戰的情況下，干擾兩個級別6儀式地點。', '既然我們已經測試過他們的兵力儲備，現在我們的焦點會是那些黑暗方尖碑，以及它們所提供的恩澤。\n\n這需要嚴密的監視，而且當你調查現場時，肯定也會遇上更大量的巡邏隊。對於像你這樣的人來說應該不算太難。\n\n避開他們…或者如果有必要的話，就解決掉他們。', '', '', '', '', '', '', 69587),
(96731, 'zhTW', '進階儀式地點研究：第4週（共6週）', '在啟用增援和魔法警鈴挑戰的情況下，干擾兩個級別6儀式地點。', '就在你離開後，我冒出了一個想法。\n\n我們已經削減了他們的兵力，但也看到他們能夠召喚更多援軍。\n\n我想測試他們後備力量的極限。\n\n如果你能應付這一系列特定的挑戰，我保證會再給你一把開啟寶庫的鑰匙。', '', '', '', '', '', '', 69587),
(96730, 'zhTW', '儀式地點研究：第3週（共3週）', '在啟用餘燼挑戰的情況下，干擾兩個級別6儀式地點。', '我想我即將有一項重大發現。這些最新的儀式涉及一種我前所未聞的魔法，其形態為強大的餘燼，並利用部隊自身的能量來增強其領袖的力量。\n\n如果你去干擾這些儀式並向我回報你的發現，我也許能將這種魔法轉為我們所用。別那樣看著我。我當然是指用在我的惡魔僕從身上。你以為我是指像你這樣的士兵嗎？\n\n要進行那樣的試驗還太早了。帶著你的發現回來向我回報！', '', '', '', '', '', '', 69587),
(96729, 'zhTW', '儀式地點研究：第2週（共3週）', '在啟用惡意恩澤挑戰的情況下，干擾兩個級別6儀式地點。', '$r，我有你的下一個任務了。我需要你研究這些惡意恩澤以及其黑暗方尖碑的韌性。\n\n它們集中魔法的效果異常出色，且恩澤的多樣性也非常有趣。不過，我還需要更多資料。\n\n當你干擾下一個儀式地點時，我需要你在這些惡意恩澤存在的情況下行動。', '', '', '', '', '', '', 69587),
(96728, 'zhTW', '儀式地點研究：第1週（共3週）', '在啟用增援挑戰的情況下，干擾兩個級別6儀式地點。', '在你回報說已經削弱了他們的兵力後，我不禁開始思考。\n\n他們究竟是用什麼手段招募成員的？難道這些士兵也和他們的領袖一樣狂熱嗎？\n\n我在想，如果我們大舉消滅他們的部隊，是否能徹底擊垮他們的戰鬥意志。我擔心，只靠一次教訓恐怕還不足以確定答案。', '', '', '', '', '', '', 69587),
(96727, 'zhTW', '至暗之夜：異界決戰場', '在至暗之夜中，於衛爾或奈格塔干擾敵人的基地。', '我們在永歌森林與祖阿曼挫敗虛無襲擊的努力取得了顯著成效，但如果我們找不到方法阻止侵略者踏上我們的土地，他們將會耗盡我們的鮮血，直到我們再也支撐不住。\n\n裂刃梅拉最近發現了敵方兩座基地的位置。她打算主動出擊。你願意協助她的突擊隊嗎？\n\n在這黑暗的時期，你的努力絕不會被忽視！', '', '', '', '', '', '', 69587),
(96720, 'zhTW', '決戰奈格塔', '透過完成世界任務、殺死稀有生物、完成事件和搜刮寶藏來干擾奈格塔的赫哈達。', '這真是個奇妙的世界，你說是吧？\n\n赫哈達肯定發現了某種重要的東西。\n\n熔爐的惡臭，表示他們正在掠取這遙遠世界中所有的財寶和資源。\n\n如果你能干擾他們在這裡進行的行動，就能為你寶貴的世界換來一點喘息的時間。\n\n去做你最擅長的事吧，我親愛的小怪物。', '', '', '', '', '', '', 69587),
(96718, 'zhTW', '決戰奈格塔（英雄）', '透過完成世界任務、殺死稀有生物、完成事件和搜刮寶藏來干擾奈格塔的赫哈達。', '這真是個奇妙的世界，你說是吧？\n\n赫哈達肯定發現了某種重要的東西。\n\n熔爐的惡臭，表示他們正在掠取這遙遠世界中所有的財寶和資源。\n\n如果你能干擾他們在這裡進行的行動，就能為你寶貴的世界換來一點喘息的時間。\n\n去做你最擅長的事吧，我親愛的小怪物。', '', '', '', '', '', '', 69587),
(96717, 'zhTW', '決戰奈格塔', '透過完成世界任務、殺死稀有生物、完成事件和搜刮寶藏來干擾奈格塔的赫哈達。', '這真是個奇妙的世界，你說是吧？\n\n赫哈達肯定發現了某種重要的東西。\n\n熔爐的惡臭，表示他們正在掠取這遙遠世界中所有的財寶和資源。\n\n如果你能干擾他們在這裡進行的行動，就能為你寶貴的世界換來一點喘息的時間。\n\n去做你最擅長的事吧，我親愛的小怪物。', '', '', '', '', '', '', 69587),
(96716, 'zhTW', '決戰衛爾', '透過完成世界任務、殺死稀有生物、完成事件和搜刮寶藏來干擾衛爾的多曼納爾部隊。', '敵人在衛爾的勢力或許很強，但並非無懈可擊。\n\n我們每擊倒一隻怪物，就讓他們少一個手下能威脅我們的世界。\n\n前往凍結之地，在他們的要塞大肆破壞吧。\n\n絕對別手下留情，$n。', '', '', '', '', '', '', 69587),
(96714, 'zhTW', '決戰衛爾（英雄）', '在英雄階級下，透過完成世界任務、殺死稀有生物、完成事件和搜刮寶藏來干擾衛爾的多曼納爾部隊。', '敵人在衛爾的勢力或許很強，但並非無懈可擊。\n\n我們每擊倒一隻怪物，就讓他們少一個手下能威脅我們的世界。\n\n前往凍結之地，在他們的要塞大肆破壞吧。\n\n絕對別手下留情，$n。', '', '', '', '', '', '', 69587),
(96713, 'zhTW', '決戰衛爾', '透過完成世界任務、殺死稀有生物、完成事件和搜刮寶藏來干擾衛爾的多曼納爾部隊。', '敵人在衛爾的勢力或許很強，但並非無懈可擊。\n\n我們每擊倒一隻怪物，就讓他們少一個手下能威脅我們的世界。\n\n前往凍結之地，在他們的要塞大肆破壞吧。\n\n絕對別手下留情，$n。', '', '', '', '', '', '', 69587),
(96708, 'zhTW', '飛向虛無，闖入風暴！', '在虛無風暴的咆哮峰與梅拉和突擊隊會合。', '雖然看起來不多，但我們只能爭取到這些盟友了。\n\n是時候出發了。\n\n我們的部隊正在咆哮峰集結，虛無風暴的能量將讓我們得以開啟通往這些世界的道路。\n\n我會在那裡與你碰面。趁我還在這，我需要先去拿一件這次任務必備的東西。', '', '', '', '', '', '在虛無風暴的咆哮峰與裂刃梅拉碰面。', 69587),
(96703, 'zhTW', '暗界精兵', '為梅拉的遠征隊招募指揮官塔拉桑和光鑄德萊尼。', '當赫哈達發動攻擊時，我們很快就得知了他們過去和聖光軍團之間的衝突。\n\n指揮官塔拉桑一直提供我們有關這些以太族的情報。他的部下也準備好加入我們的行動了。\n\n我已請求他們提供協助，幫助我們設置前線營地。\n\n協助他們進行準備，並通知指揮官我們很快就會出動。', '', '', '', '', '', '', 69587),
(96699, 'zhTW', '蘑菇之頂觸鬚投索', '', '', '', '', '', '', '', '', 69587),
(96698, 'zhTW', '沼地觸鬚投索', '', '', '', '', '', '', '', '', 69587),
(96697, 'zhTW', '撤離海岸觸鬚投索', '', '', '', '', '', '', '', '', 69587),
(96696, 'zhTW', '營地觸鬚投索', '', '', '', '', '', '', '', '', 69587),
(96695, 'zhTW', '繫留場觸鬚投索', '', '', '', '', '', '', '', '', 69587),
(96693, 'zhTW', '中樞港口觸鬚投索', '', '', '', '', '', '', '', '', 69587),
(96691, 'zhTW', '指揮所觸鬚投索', '', '', '', '', '', '', '', '', 69587),
(96689, 'zhTW', '軍事要塞觸鬚投索', '', '', '', '', '', '', '', '', 69587),
(96688, 'zhTW', '真菌熔爐觸鬚投索', '', '', '', '', '', '', '', '', 69587),
(96668, 'zhTW', '壓制孢子風暴', '', '', '', '', '', '', '', '', 69587),
(96660, 'zhTW', '殘骸觸鬚投索', '', '', '', '', '', '', '', '', 69587),
(96651, 'zhTW', '壓制孢子風暴', '', '', '', '', '', '', '', '', 69587),
(96650, 'zhTW', '壓制孢子風暴', '', '', '', '', '', '', '', '', 69587),
(96649, 'zhTW', '迷霧紋章頂點', '把10個精兵迷霧紋章帶給銀月城的維史康，之後用來換取一批冒險者迷霧紋章。', '紋章的型態不一，你可以在不同階級間轉化紋章。\n\n如果你手上的紋章無法用於你目前的裝備，我可以把那些精煉成較低階級的紋章。一旦你裝備升級，我們可以反向操作，把低階的紋章轉化成高階的。\n\n先來做個簡單的練習吧。把那些精兵迷霧紋章拿給我，我來轉化成冒險者迷霧紋章。', '', '', '', '', '', '', 69587),
(96644, 'zhTW', '惡意精華', '在阿塔烏特克寶庫深處收集邪惡毒液。', '我需要毒藥，純粹、強力的毒。從地面滲出的毒液會被其他東西稀釋，純度太低了。你得找到最惡毒的泉源才行。\n\n搜尋寶庫深處。那才是真正毒液的源頭。', '', '', '', '', '', '', 69587),
(96643, 'zhTW', '從其所來之處', '在阿塔烏特克寶庫擊敗一個遠古強敵。遠古強敵會在完成神殿入侵點後復生。', '你感覺到了嗎？古老的事物潛伏在神殿裡，正等待著再次甦醒。它們被戰鬥的聲響所吸引，渴望將暴力傾瀉在你身上。找到其中一個古老的強敵，確保它再也無法復生。', '', '', '', '', '', '', 69587),
(96642, 'zhTW', '果斷入侵', '在阿塔烏特克寶庫中成功完成神殿入侵點。', '這些攻擊只是第一步。我們絕不能讓敵人恢復。首先我們要重創牠們，削弱牠們的實力。接著，我們要集結所有力量，發動迅猛的攻擊。\n\n我們沒有足夠的兵力打持久戰。當進攻神殿入侵點的時刻來臨，你最好已經做足準備。\n\n集結你的盟友。我們的敵人非常強大。', '', '', '', '', '', '向領軍阿杜馬提回報。', 69587),
(96641, 'zhTW', '攻擊不懈', '在阿塔烏特克寶庫中完成神殿攻擊。', '有人說烏拉特克的手下無窮無盡，我們永遠殺不完。\n\n<索丘咧嘴笑著。>\n\n不過我喜歡挑戰。你呢？去痛扁敵人，我們看看牠們到底有多麼無窮無盡。', '', '', '', '', '', '向領軍阿杜馬提回報。', 69587),
(96639, 'zhTW', '在神殿巡邏', '在阿塔烏特克寶庫中完成神殿巡邏。', '沒時間在這發呆了。你有強健的體魄和敏銳的雙眼，最好讓它們派上用場。我們承擔不起讓那些毒蛇推進任何一寸的代價。\n\n在神殿裡巡邏。如果你看到有人需要幫助，就幫他們一把。要是你發現有人已經回天乏術？那就確保那些傷害他們的惡徒付出代價。', '', '', '', '', '', '向領軍阿杜馬提回報。', 69587),
(96637, 'zhTW', '精兵研討會', '取得一個精兵軌跡裝備和$2oa個精兵迷霧紋章。和庫佐斯交談，使用紋章來升級精兵軌跡物品，然後回到銀月城找維史康。', '那東西的來源力量更為強大！\n\n升級效果會隨著物品強度昇華。更高品質的物品，力量也更強大。接下來的步驟呢，我會需要精兵裝備和精兵迷霧紋章。\n\n只要你把東西帶來，庫佐斯和我就能繼續進行強化。', '', '', '', '', '', '', 69587),
(96635, 'zhTW', '升級演習', '透過擊敗獨特的生物、通過團隊副本、完成世界活動或領取寶箱戰利品來取得$1oa個冒險者迷霧紋章。和庫佐斯交談，使用紋章來升級冒險者軌跡物品，然後回到銀月城找維史康。', '庫佐斯和我的技藝又更進了一步，我們能為你的裝備灌注更強大的力量。\n\n為了解放完整潛力，我們會需要迷霧紋章。紋章可以從各種試煉中取得，越危險的地方可取得更強大的紋章。但就算是冒險者迷霧紋章也有著強大的能力。\n\n帶五十個冒險者迷霧紋章來給我，$n。我們來看看你裝備的真正潛能吧。', '', '', '', '', '', '', 69587),
(96633, 'zhTW', '裝備講座', '獲得一件冒險者軌跡裝備，然後回到銀月城找維史康。', '歡迎回來，$n！我正和銀月城這裡的工匠們繼續進行合作。他們的技巧越來越精湛了。用晨曦的精華灌注裝備不只是理論，已經成為一種藝術了。\n\n我等不及要繼續工作了。再拿一件冒險者裝備來給我，看看這些改良的工法實際運用時效果如何。\n\n總是會有很多人需要有力幫手的。出手幫忙，他們就會回報你。', '', '', '', '', '', '', 69587),
(96625, 'zhTW', '鬼靈鬥士', '', '', '', '', '', '', '', '', 69587),
(96623, 'zhTW', '翻覆的堆肥', '', '', '', '', '', '', '', '', 69587),
(96618, 'zhTW', '緩解風暴', '', '', '', '', '', '', '', '', 69587),
(96617, 'zhTW', '緩解風暴', '', '', '', '', '', '', '', '', 69587),
(96615, 'zhTW', '遠古奇趣：通用', '使用並為你的探究夥伴裝備一件通用古董。', '<你拿著古董，發現它正散發著微弱的光芒。這看起來很重要。>', '', '', '', '', '', '', 69587),
(96614, 'zhTW', '經火鍛造', '', '', '', '', '', '', '', '', 69587),
(96612, 'zhTW', '遠古奇趣：戰鬥', '使用並為你的探究夥伴裝備一件戰鬥古董。', '<你拿著古董，發現它正散發著微弱的光芒。這看起來很重要。>', '', '', '', '', '', '', 69587),
